// MediaPermissionPlugin — the runtime microphone-permission bridge.
//
// Source of truth lives in src-tauri/android-extras/ (committed); the build
// copies it into gen/android/app/src/main/java/com/audhd/resonance_sistrum/plugin/
// via scripts/sync-android-extras.mjs, because gen/ is regenerated by
// `tauri android init` and nothing hand-placed there survives. Loaded
// reflectively from Rust (media_permission.rs) — the @TauriPlugin annotation
// both drives the permission machinery in the app.tauri Plugin base class and
// matches the R8 keep rule for plugin classes.
//
// Carried from resonance-compass's plugin of the same name (v3 Phase 2, proven
// on the S25) in the Android microphone wave, 2026-08-20 — the microphone
// alias and the ndk-context hand-over only. This body scans no library, so the
// media/storage aliases and the becoming-noisy receiver did not cross.

package com.audhd.resonance_sistrum.plugin

import android.app.Activity
import android.content.Context
import app.tauri.PermissionState
import app.tauri.annotation.Command
import app.tauri.annotation.Permission
import app.tauri.annotation.PermissionCallback
import app.tauri.annotation.TauriPlugin
import app.tauri.plugin.Invoke
import app.tauri.plugin.JSObject
import app.tauri.plugin.Plugin

private const val ALIAS_MIC = "mic"

@TauriPlugin(
  permissions = [
    Permission(strings = ["android.permission.RECORD_AUDIO"], alias = ALIAS_MIC)
  ]
)
class MediaPermissionPlugin(activity: Activity) : Plugin(activity) {
  companion object {
    @Volatile private var ndkContextInitialized = false
  }

  init {
    // cpal's oboe backend reads the JNI context via Rust's ndk-context crate,
    // which nothing in the tauri stack initializes — hand it over once so an
    // input stream can open at all. The native lib is already loaded: plugin
    // construction is driven from Rust.
    if (!ndkContextInitialized) {
      ndkContextInitialized = true
      nativeInitNdkContext(activity.applicationContext)
    }
  }

  private external fun nativeInitNdkContext(context: Context)

  // ── The microphone (RECORD_AUDIO) ──────────────────────────────────────────

  @Command
  fun checkMicPermission(invoke: Invoke) {
    invoke.resolve(micStateResult())
  }

  @Command
  fun requestMicPermission(invoke: Invoke) {
    if (getPermissionState(ALIAS_MIC) == PermissionState.GRANTED) {
      invoke.resolve(micStateResult())
    } else {
      requestPermissionForAlias(ALIAS_MIC, invoke, "micPermissionCallback")
    }
  }

  @PermissionCallback
  fun micPermissionCallback(invoke: Invoke) {
    invoke.resolve(micStateResult())
  }

  private fun micStateResult(): JSObject {
    val res = JSObject()
    res.put("granted", getPermissionState(ALIAS_MIC) == PermissionState.GRANTED)
    return res
  }
}
